<?php
require __DIR__.'/../includes/library_equipment_ledgers.php';
function check($v,$m){if(!$v)throw new RuntimeException($m);}
$base=['borrower'=>'Vương Văn Quân','subject'=>'GDTC','school_year'=>'2026 - 2027'];$rows=[];foreach(['2026-11-23','2026-11-09','2026-11-16','2026-11-10']as$i=>$date)$rows[]=array_merge($base,['id'=>'r'.$i,'batch_id'=>'old'.$i,'borrowed_at'=>$date,'equipment_name'=>$i===3?'Bóng ném':'Đệm nhảy cao','quantity'=>$i===3?30:1,'returned_at'=>$i===0?'':'2026-11-19']);
$rows[]=array_merge($base,['subject'=>'Sinh học','id'=>'other-subject']);$rows[]=array_merge($base,['school_year'=>'2025-2026','id'=>'old-year']);$rows[]=array_merge($base,['borrower'=>'Vũ Thị Thanh Hương','id'=>'other-teacher']);$before=serialize($rows);$books=lib_eq_ledgers($rows);check(count($books)===4,'One ledger per teacher/subject/year');$id=lib_eq_ledger_id($base);check(count($books[$id]['rows'])===4&&$books[$id]['open']===1,'All old batches combined with return states intact');check(array_column($books[$id]['rows'],'id')===['r1','r3','r2','r0'],'Chronological detail rows');check(lib_eq_batch_ledger($rows,'old1')===$id,'Old print URL resolves whole ledger');check(lib_eq_ledger_id(array_merge($base,['borrower'=>' VƯƠNG  VĂN QUÂN ','subject'=>'gdtc','school_year'=>'2026-2027']))===$id,'Whitespace/case/year separators do not duplicate ledger');check(lib_eq_ledger_id(array_merge($base,['ledger_id'=>'untrusted']))===$id,'Stored arbitrary ledger ID not trusted');check(lib_eq_batch_ledger(array_merge($rows,[array_merge($base,['borrower'=>'Other','batch_id'=>'old1'])]),'old1')==='','Ambiguous old batch fails closed');check(lib_eq_year(['borrowed_at'=>'2025-10-01'])==='2025 - 2026','Legacy year inferred from borrow date');check(serialize($rows)===$before,'Read-time grouping never rewrites or drops history');echo "PASS equipment ledgers: four legacy batches to one book, teacher/subject/year isolation, stable IDs, chronological rows, return states and no data mutation\n";
